{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret opstiller to opfundne former for handicaptillæg (tilrettelæggelsesstillæg og meromkostningstillæg) og angiver 'erhvervsaktiverende dagpenge eller studiepenge' som betingelse. Det findes ikke i kilderne, som kræver almindelige SU-betingelser, videregående uddannelse eller EUD og en varig funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen. Svaret er derfor i væsentlig grad forkert."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Ingen af de tre kritiske elementer er dækket: de almindelige SU-/slutlånsbetingelser, indskrivning på en videregående uddannelse eller dansk EUD, og varig funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde. Kravet om at tillægget gives sammen med SU-stipendium eller slutlån nævnes heller ikke."},
    "c03_direct_relevance": {"label": "not_met", "reason": "Spørgsmålet er, hvad betingelserne for SU-handicaptillæg er. Svaret angiver betingelser, der ikke er de gældende, og indeholder en opdeling, som ikke findes i materialet. Det besvarer derfor ikke de væsentlige dele af spørgsmålet."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret henviser ikke til nogen identificerbar kilde som lov, bestemmelse eller vejledning."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om påstandene understøttes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer uunderstøttede regler: to typer tillæg, krav om erhvervsaktiverende dagpenge eller studiepenge, krav om særlige hjælpemidler for at gennemføre uddannelsen og krav om ekstra udgifter på grund af handicap eller sygdom. Ingen af dem har støtte i kildematerialet."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Svaret bevarer ikke de begrænsninger, der ændrer betydningen: kravet om en varig funktionsnedsættelse og kravet om meget betydelige begrænsninger i erhvervsevnen. Det angiver heller ikke, at uddannelsen skal være videregående eller dansk EUD. Rubrikken kræver ingen særskilt standardadvarsel, men de materielle begrænsninger mangler."},
    "c09_reasoning_coherence": {"label": "not_met", "reason": "Svaret er internt uklart. Det indleder med to former for tillæg og opstiller to lister, som begge bygger på et uunderstøttet grundkrav. Derfor følger konklusionen ikke af de regler, der fremgår af kilderne."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret præsenterer opfundne betingelser som absolutte krav ('Du skal have ...'), selvom de ikke findes i kilderne. Kildernes modalitet gengives derfor ikke præcist."}
  },
  "xhaile_coverage": {
    "A1": {"label": "no", "reason": "Svaret nævner ikke de almindelige betingelser for SU eller slutlån. 'Erhvervsaktiverende dagpenge eller studiepenge' er ikke det samme."},
    "A2": {"label": "no", "reason": "Svaret nævner ikke, at man skal gå på en videregående uddannelse eller dansk EUD."},
    "A3": {"label": "no", "reason": "Svaret nævner ikke varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde. Det nævner kun en uspecificeret 'begrænsning', som kræver hjælpemidler, eller 'handicap eller sygdom' med ekstra udgifter."},
    "A4": {"label": "no", "reason": "Svaret nævner ikke kravet om at være indskrevet på og gennemgå en uddannelse, der berettiger til SU eller slutlån."},
    "A6": {"label": "no", "reason": "Svaret nævner ikke EUD, EUX eller afgrænsningen over for erhvervslignende uddannelse i udlandet."}
  },
  "overall_notes": "Svaret er juridisk forkert og mangler alle tre kritiske elementer. Det opfinder to typer tillæg og betingelser, som ikke findes i kilderne, og angiver ingen kilde. C04 er not_met, og C05 og C06 er derfor not_assessable."
}

